# Timing on bench-like data
_r = random.Random(7)
ys = [_r.uniform(0,1) for _ in range(3000)]
W=300
N=len(ys)-W+1
def bench(name, fn):
    fn()  # warm
    best=float('inf')
    for _ in range(3):
        t=time.perf_counter(); out=fn(); best=min(best, time.perf_counter()-t)
    print("BENCH", name, "%.4fs" % best, "first3", out[:3] if isinstance(out, list) else out)
    return out

def f_naive():
    out=[]
    for i in range(N):
        total=0.0
        for j in range(i,i+W):
            total=total+float(ys[j])*1.0
        out.append(total/W)
    return out

def f_sum():
    return [sum(ys[i:i+W])/W for i in range(N)]

def f_fsum():
    return [math.fsum(ys[i:i+W])/W for i in range(N)]

def f_accum_list():
    acc=itertools.accumulate
    return [list(acc(ys[i:i+W], initial=0.0))[-1]/W for i in range(N)]

def f_reduce():
    red=functools.reduce; add=operator.add
    return [red(add, ys[i:i+W], 0.0)/W for i in range(N)]

ysub=[F(x) for x in ys]
def f_sum_sub():
    return [sum(ysub[i:i+W])/W for i in range(N)]

ycomp=[complex(x,0.0) for x in ys]
def f_sum_comp():
